#ifndef ISODUR_INTERNAL_H
#define ISODUR_INTERNAL_H

#include <isodur/isodur.h>

enum {
  ISODUR__YEAR,
  ISODUR__MONTH,
  ISODUR__WEEK,
  ISODUR__DAY,
  ISODUR__HOUR,
  ISODUR__MINUTE,
  ISODUR__SECOND,
  ISODUR__NUNITS
};

#define ISODUR__WORD 32

struct isodur_units {
  char lang[ISODUR__WORD];
  char one[ISODUR__NUNITS][ISODUR__WORD];
  char other[ISODUR__NUNITS][ISODUR__WORD];
  char and_word[ISODUR__WORD];
  unsigned seen;
};

extern const char *const isodur__unit_keys[ISODUR__NUNITS];

const char *isodur__skip_space(const char *s);
long isodur__seconds_ms(double seconds);
#include "internal.h"

const char *isodur_version(void)
{
  return ISODUR_VERSION_STRING;
}

const char *isodur_strerror(int err)
{
  switch (err) {
  case ISODUR_OK: return "ok";
  case ISODUR_ESYNTAX: return "invalid duration";
  case ISODUR_ERANGE: return "value out of range";
  case ISODUR_ENOMEM: return "out of memory";
  case ISODUR_EIO: return "cannot read unit table";
  case ISODUR_ETABLE: return "malformed unit table";
  case ISODUR_ENOLANG: return "unknown language";
  case ISODUR_ENOUNITS: return "no unit table";
  default: return "unknown error";
  }
}
